34	/**
35	 * A persistent key-(value-timestamp) store based on RocksDB.
36	 */
37	public class RocksDBTimestampedStore extends RocksDBStore implements TimestampedBytesStore {
38	    private static final Logger log = LoggerFactory.getLogger(RocksDBTimestampedStore.class);
39	
40	    static final byte[] TIMESTAMPED_VALUES_COLUMN_FAMILY_NAME = "keyValueWithTimestamp".getBytes(StandardCharsets.UTF_8);
41	
42	    public RocksDBTimestampedStore(final String name,
43	                                   final String metricsScope) {
44	        super(name, metricsScope);
45	    }
46	
47	    RocksDBTimestampedStore(final String name,
48	                            final String parentDir,
49	                            final RocksDBMetricsRecorder metricsRecorder) {
50	        super(name, parentDir, metricsRecorder);
51	    }
52	
53	    @Override
54	    void openRocksDB(final DBOptions dbOptions,
55	                     final ColumnFamilyOptions columnFamilyOptions) {
56	        final List<ColumnFamilyHandle> columnFamilies = openRocksDB(
57	            dbOptions,
58	            new ColumnFamilyDescriptor(RocksDB.DEFAULT_COLUMN_FAMILY, columnFamilyOptions),
59	            new ColumnFamilyDescriptor(TIMESTAMPED_VALUES_COLUMN_FAMILY_NAME, columnFamilyOptions)
60	        );
61	        final ColumnFamilyHandle noTimestampColumnFamily = columnFamilies.get(0);
62	        final ColumnFamilyHandle withTimestampColumnFamily = columnFamilies.get(1);
63	
64	        final RocksIterator noTimestampsIter = db.newIterator(noTimestampColumnFamily);
65	        noTimestampsIter.seekToFirst();
66	        if (noTimestampsIter.isValid()) {
67	            log.info("Opening store {} in upgrade mode", name);
68	            cfAccessor = new DualColumnFamilyAccessor(
69	                noTimestampColumnFamily,
70	                withTimestampColumnFamily,
71	                TimestampedBytesStore::convertToTimestampedFormat,
72	                this
73	            );
74	        } else {
75	            log.info("Opening store {} in regular mode", name);
76	            cfAccessor = new SingleColumnFamilyAccessor(withTimestampColumnFamily);
77	            noTimestampColumnFamily.close();
78	        }
79	        noTimestampsIter.close();
80	    }
81	
82	}
