package org.apache.kafka.streams.state.internals;

import org.apache.kafka.common.TopicPartition;
import org.apache.kafka.common.serialization.Serdes;
import org.apache.kafka.common.serialization.StringSerializer;
import org.apache.kafka.streams.errors.ProcessorStateException;
import org.apache.kafka.streams.state.internals.RocksDBStore.DBAccessor;

import org.rocksdb.ColumnFamilyHandle;
import org.rocksdb.RocksDBException;

import java.util.Map;
import java.util.concurrent.atomic.AtomicBoolean;

/**
 * Abstract base class for {@link RocksDBStore.ColumnFamilyAccessor} implementations that maintains
 * the lifecycle status and the committed changelog offsets of a store in a dedicated offsets
 * column family.
 * <p>
 * The offsets column family holds a special {@code status} key that tracks whether the store is
 * currently open ({@code 1L}) or closed ({@code 0L}), as well as one entry per changelog
 * {@link TopicPartition} mapping its {@link TopicPartition#toString() string representation} to the
 * last committed offset. This allows a store to detect whether it was previously left open (and
 * therefore may contain uncommitted data under exactly-once semantics), and to recover the offsets
 * that were durably committed to the store.
 */
abstract class AbstractColumnFamilyAccessor implements RocksDBStore.ColumnFamilyAccessor {

    private final StringSerializer stringSerializer = new StringSerializer();
    private final Serdes.LongSerde longSerde = new Serdes.LongSerde();

    private final byte[] statusKey = stringSerializer.serialize(null, "status");
    private final byte[] openState = longSerde.serializer().serialize(null, 1L);
    private final byte[] closedState = longSerde.serializer().serialize(null, 0L);

    protected final ColumnFamilyHandle offsetColumnFamilyHandle;
    protected final AtomicBoolean storeOpen;

    AbstractColumnFamilyAccessor(final ColumnFamilyHandle offsetColumnFamilyHandle,
                                 final AtomicBoolean storeOpen) {
        this.offsetColumnFamilyHandle = offsetColumnFamilyHandle;
        this.storeOpen = storeOpen;
    }

    @Override
    public final void open(final DBAccessor accessor, final boolean ignoreInvalidState) throws RocksDBException {
        final byte[] statusBytes = accessor.get(offsetColumnFamilyHandle, statusKey);
        final long status = statusBytes == null ? 0L : longSerde.deserializer().deserialize(null, statusBytes);

        if (status == 0L) {
            // The store is either freshly created (no status yet) or was cleanly closed;
            // mark it as open.
            accessor.put(offsetColumnFamilyHandle, statusKey, openState);
            storeOpen.set(true);
        } else {
            // The store was previously left open, i.e. it was not cleanly closed.
            if (!ignoreInvalidState) {
                throw new ProcessorStateException(
                    "Invalid state during store open. Expected state to be either empty or closed");
            }
            storeOpen.set(true);
            accessor.put(offsetColumnFamilyHandle, statusKey, openState);
        }
    }

    @Override
    public void close(final DBAccessor accessor) throws RocksDBException {
        try {
            accessor.put(offsetColumnFamilyHandle, statusKey, closedState);
            storeOpen.set(false);
        } finally {
            offsetColumnFamilyHandle.close();
        }
    }

    @Override
    public final void commit(final DBAccessor accessor,
                             final Map<TopicPartition, Long> changelogOffsets) throws RocksDBException {
        for (final Map.Entry<TopicPartition, Long> entry : changelogOffsets.entrySet()) {
            final byte[] key = stringSerializer.serialize(null, entry.getKey().toString());
            final byte[] value = longSerde.serializer().serialize(null, entry.getValue());
            accessor.put(offsetColumnFamilyHandle, key, value);
        }
        flush(accessor, offsetColumnFamilyHandle);
    }

    @Override
    public final Long getCommittedOffset(final DBAccessor accessor,
                                         final TopicPartition partition) throws RocksDBException {
        final byte[] valueBytes = accessor.get(
            offsetColumnFamilyHandle,
            stringSerializer.serialize(null, partition.toString()));
        if (valueBytes == null) {
            return null;
        }
        return longSerde.deserializer().deserialize(null, valueBytes);
    }

    /**
     * Flush the data column families managed by this accessor together with the offsets column
     * family, so that the committed offsets are persisted atomically with the data they refer to.
     *
     * @param accessor                  the {@link DBAccessor} to flush through
     * @param offsetColumnFamilyHandle  the handle of the offsets column family
     */
    protected abstract void flush(final DBAccessor accessor,
                                  final ColumnFamilyHandle offsetColumnFamilyHandle) throws RocksDBException;
}
